  string GearDescription(GearDefinition g){int b=g.BaseBonus;if(b==0)return "A cosmetic piece for your collection.";string text=g.Slot=="HEAD"?"Daily quests: +"+b+" XP.":g.Slot=="CHEST"?"All quests: +"+Math.Max(1,b/2)+" XP.":g.Slot=="HANDS"?"Non-daily quests: +"+Math.Max(1,b-1)+" XP.":g.Slot=="WEAPON"?"Non-daily quests: +"+b+" XP.":g.Slot=="LEGS"?"Non-daily quests due today/overdue or with 2+ steps: +"+Math.Max(1,b/2)+" XP.":g.Slot=="OFFHAND"?"Non-daily quests with steps: +"+Math.Max(1,b/2)+" XP.":g.Slot=="ACCESSORY"?"All quests: +1 XP.":g.Slot=="RING"?"Non-daily quests: +1 XP.":"Cosmetic for the current quest types.";if(g.Rarity=="EPIC"||g.Rarity=="UNIQUE")text+=" Plus +"+(g.Rarity=="EPIC"?2:3)+" XP on every quest.";return text;}
  void CompleteQuests(IEnumerable<Quest> quests){var list=quests.ToList();int completed=list.Count(q=>!q.Done&&!q.Archived),xp=0,coins=list.Where(q=>!q.Done&&!q.Archived).Sum(q=>q.XP/5),bossIndex=data.Journey.BossIndex,bossMaxHP=data.Journey.BossMaxHP,history=data.Journey.History.Count;bool wasEgg=Journey.ActivePet(data).EggStage<4;var owned=new HashSet<string>(data.Journey.Gear);if(Change(()=>{xp=Game.Complete(data,list,DateTime.Today);selected.Clear();},"Progress saved.")){status.Text="Well done! +"+xp+" XP · +"+coins+" coins · Your familiar and boss progressed.";bool defeated=data.Journey.History.Count>history&&data.Journey.History.Take(data.Journey.History.Count-history).Any(h=>h.Index==bossIndex&&h.Outcome=="Defeated");var pet=Journey.ActivePet(data);var rewards=new List<CompletionReward>{new CompletionReward("+"+coins+" coins",CoinArtwork()),new CompletionReward("+"+(completed*20)+(wasEgg?" growth XP":" familiar XP"),Artwork(Journey.Definition(pet).Art[Journey.Stage(pet)]))};foreach(var drop in data.Journey.Gear.Where(id=>!owned.Contains(id)).Select(id=>GearCatalog.All.Single(g=>g.Id==id)))rewards.Add(new CompletionReward(drop.Name,Artwork(GearSheets[drop.Sheet],drop.Tile)));using(var dialog=new QuestVictoryDialog(Journey.Bosses[bossIndex],Artwork(bossIndex<9?"weekly_monsters_1_9":"weekly_monsters_10_18",bossIndex%9),xp,bossMaxHP,defeated,data.Journey.BossHP,Journey.Bosses[data.Journey.BossIndex],rewards))dialog.ShowDialog(this);}}
  Image CoinArtwork(){const string key="completion-coins";if(artCache.ContainsKey(key))return artCache[key];var image=new Bitmap(96,96);using(var g=Graphics.FromImage(image)){g.SmoothingMode=SmoothingMode.AntiAlias;using(var coin=new SolidBrush(Color.FromArgb(222,165,54)))g.FillEllipse(coin,8,8,80,80);using(var edge=new Pen(Theme.Gold,6))g.DrawEllipse(edge,12,12,72,72);TextRenderer.DrawText(g,"★",new Font("Segoe UI Symbol",30,FontStyle.Bold),new Rectangle(12,12,72,72),Color.FromArgb(255,238,170),TextFormatFlags.HorizontalCenter|TextFormatFlags.VerticalCenter);}artCache.Add(key,image);return image;}
